WITH cases(id,bid,acq,cost,payout,expected) AS (VALUES('collected',90000,35000,0,5000,50000),('delivered',120000,35000,40000,5000,40000),('negative',55000,40000,20000,0,-5000),('unknown_bid',NULL,40000,20000,0,NULL),('unknown_cost',90000,40000,NULL,0,NULL)) SELECT id,bid-acq-cost-payout calculated_cents,expected,(bid-acq-cost-payout) IS NOT DISTINCT FROM expected passed FROM cases;
